function updateFighter(f,dt,enemyControlled=false){f.cool=Math.max(0,f.cool-dt);f.stun=Math.max(0,f.stun-dt);f.attack=Math.max(0,f.attack-dt);f.jump=Math.max(0,f.jump-dt);const other=f===player?enemy:player;const dx=other.root.position.x-f.root.position.x,dist=Math.abs(dx);f.guard=false;let moving=0;
if(enemyControlled){aiThink-=dt;if(aiThink<=0){aiThink=.18+Math.random()*.22;if(dist>2.05){moving=Math.sign(dx);f.guard=false}else if(f.health<other.health&&Math.random()<.42)f.guard=true;else if(Math.random()<.68)attack(f,Math.random()<.66?'punch':'kick');else f.guard=true}if(dist>2.6)moving=Math.sign(dx);else if(dist<1.45&&Math.random()<.015)moving=-Math.sign(dx)}else if(!f.stun){moving=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);f.guard=!!keys.l;if((keys.w||keys.arrowup)&&f.jump<=0)f.jump=.62;f.crouch=!!keys.s}
if(f.stun>0){moving=0;f.guard=false}if(f.guard)moving*=.32;const speed=enemyControlled?2.45:3.35;f.root.position.x+=moving*speed*dt;f.root.position.x=THREE.MathUtils.clamp(f.root.position.x,-4.25,4.25);f.walk+=dt*(moving?9:2);
const jumping=f.jump>0;f.root.position.y=jumping?Math.sin((.62-f.jump)/.62*Math.PI)*.82:0;f.rig.position.y=f.root.position.y;f.rig.position.z=THREE.MathUtils.damp(f.rig.position.z,0,9,dt);f.rig.rotation.z=f.guard?0:Math.sin(f.walk)*.025*(moving?1:0);f.rig.rotation.x=f.crouch&&!enemyControlled?.18:0;
for(let i=0;i<2;i++){const arm=f.arms[i],leg=f.legs[i];arm.rotation.x=Math.sin(f.walk+(i*Math.PI))*moving*.18;arm.rotation.z=(i===0?-.08:.08)+(f.guard?-.9:0);leg.rotation.x=Math.sin(f.walk+i*Math.PI)*moving*.46;if(f.attack>0&&i===f.attackSide){const total=f.attackType==='punch'?.34:.53;const p=1-f.attack/total;if(f.attackType==='punch'){arm.rotation.x=-Math.sin(Math.min(1,p*1.35)*Math.PI)*1.75;arm.rotation.z=0;if(p>.42&&p<.58)hit(f,other,'punch')}else{leg.rotation.x=-Math.sin(Math.min(1,p*1.25)*Math.PI)*1.45;if(p>.44&&p<.6)hit(f,other,'kick')}}}
if(f.stun>0)f.rig.rotation.z=Math.sin(tick*38)*.13;if(f.guard){f.arms[0].rotation.x=-.8;f.arms[1].rotation.x=-.8;f.arms[0].rotation.z=-.42;f.arms[1].rotation.z=.42}
}
function onKey(e,down){const k=e.key.toLowerCase();keys[k]=down;if(['arrowleft','arrowright','arrowup','arrowdown',' '].includes(k))e.preventDefault();if(down&&!e.repeat){if(k==='j'||k===' ')attack(player,'punch');if(k==='k')attack(player,'kick');if(k==='enter'&&over)document.querySelector('#start').click()}}
addEventListener('keydown',e=>onKey(e,true));addEventListener('keyup',e=>onKey(e,false));document.querySelector('#start').addEventListener('click',()=>{document.querySelector('.eyebrow').textContent='NEON DISTRICT CHAMPIONSHIP · 2025';document.querySelector('.card h1').innerHTML='Last <span>Stand</span>';document.querySelector('.card p').textContent='One arena. Two legends. Only one walks out. Read your opponent, find your opening, and finish the fight.';document.querySelector('#start').textContent='Enter the arena';startGame()});
for(const btn of document.querySelectorAll('.touch-btn')){const k=btn.dataset.key;const down=e=>{e.preventDefault();keys[k]=true;btn.classList.add('down');if(k==='j')attack(player,'punch');if(k==='k')attack(player,'kick')};const up=e=>{e.preventDefault();keys[k]=false;btn.classList.remove('down')};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('pointerleave',up)}
